arguments.command:
cd /app; 
sed -i 's|^exit \$fail$|[ "$(bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] \|\| { echo "plan default"; fail=1; }
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] \|\| { echo "plan RELAY_ATTEMPTS"; fail=1; }
exit $fail|' tests/deliver_test.sh
sed -i 's|^Status: draft\.$|Status: draft. The Retry section is superseded by ADR-0009.|' docs/design/delivery.md
sed -i '0,/^## 3.4.1/s|^## 3.4.1|## Unreleased

- deliver: 4 attempts with waits of 3, 9, 27 s (ADR-0009); the count is read from `RELAY_ATTEMPTS` (RLY-731)

## 3.4.1|' CHANGELOG.md
bash bin/deliver --plan; RELAY_ATTEMPTS=6 bash bin/deliver --plan; bash scripts/verify.sh; sed -n 3,9p CHANGELOG.md; tail -4 tests/deliver_test.sh

